SEC = [
 (364, '7.0 పరిచయం – ప్రశ్న', [
  'మూడు శీర్షాలూ ఒకే సరళ రేఖపై ఉంటే త్రిభుజం ఏర్పడదు – ఒక రేఖాఖండమే వస్తుంది (లోపలి ప్రదేశం ఉండదు).']),
 (366, '7.1 సమబాహు త్రిభుజాలు', [
  'స్కేలు ఒక్కటితో సాధ్యమే కానీ చాలా ప్రయత్నాలు కావాలి. | సమర్థవంతంగా: AB = 4 సెం.మీ. గీసి, A, B ల నుండి 4 సెం.మీ. వ్యాసార్ధంతో వృత్తలేఖినితో చాపాలు గీయాలి.']),
 (368, 'నిర్మాణం – ఎందుకు సరైనది?', [
  'C బిందువు A కేంద్రంగా గల 4 సెం.మీ. చాపంపై ఉంది → AC = 4 సెం.మీ. | C బిందువు B కేంద్రంగా గల 4 సెం.మీ. చాపంపైనా ఉంది → BC = 4 సెం.మీ. | కాబట్టి AB = BC = CA = 4 సెం.మీ.']),
 (374, 'నిర్మాణాలు; Figure it Out 7.1', [
  'ప్రతిదానికీ ఒకే పద్ధతి: ఒక పొడవును ఆధారంగా గీసి, రెండు చివరల నుండి మిగతా రెండు పొడవుల వ్యాసార్ధాలతో చాపాలు గీసి, ఖండన బిందువును కలపాలి.',
  '(a) 4, 4, 6 – సమద్విబాహు. | (b) 3, 4, 5 – విషమబాహు (లంబకోణ త్రిభుజం). | (c) 1, 5, 5 – సమద్విబాహు (సన్నని త్రిభుజం). | (d) 4, 6, 8 – విషమబాహు. | (e) 3.5, 3.5, 3.5 – సమబాహు.',
  '1) వృత్త కేంద్రాన్ని వృత్తంపై ఉన్న ఏ రెండు బిందువులతో కలిపినా సమద్విబాహు త్రిభుజం – రెండు భుజాలు వ్యాసార్ధాలు (సమానం).',
  '2) రెండు వృత్తాలు (కేంద్రాలు A, B): A, B లను ఖండన బిందువు C తో కలిపితే AB = AC = BC (అన్నీ వ్యాసార్ధాలు) → సమబాహు త్రిభుజం. | ఒక వృత్తంపై ఇతర బిందువులను దాని కేంద్రం, మరో బిందువుతో కలిపితే సమద్విబాహు త్రిభుజాలు. | మూడు వృత్తాల (A, B, C) పటంలోనూ అలాగే.',
  '3, 4, 8 సెం.మీ.: A నుండి 3 సెం.మీ., B నుండి 4 సెం.మీ. చాపాలు (AB = 8) ఒకదానినొకటి చేరవు → త్రిభుజం రాదు.']),
 (376, 'మరిన్ని అసాధ్య పొడవులు', [
  '2, 3, 6: చాపాలు కలవవు → త్రిభుజం రాదు.',
  'ఇతర ఉదాహరణలు: 1, 2, 5; 4, 5, 10; 2, 2, 7; 3, 6, 9. | నమూనా: చిన్న రెండు పొడవుల మొత్తం పెద్ద దాని కంటే తక్కువ లేదా సమానం.']),
 (380, '3, 3, 7; Figure it Out 7.2 – ప్ర.1, 2', [
  '3, 3, 7: 7 > 3 + 3 → త్రిభుజం ఉండదు.',
  'పొడవులను వేరే క్రమంలో అమర్చినా లాభం లేదు – మూడు పోలికలూ (ప్రతి పొడవు, మిగతా రెండింటి మొత్తం) అవే ఉంటాయి; 30 > 10 + 15 ఎప్పుడూ విఫలమే.',
  '1) అవును: 8 > 3 + 4 = 7; 6 > 2 + 3 = 5 → నేరు దారి చుట్టు దారి కంటే పొడవు – అసాధ్యం.',
  '2) (a) 25 > 10 + 10 = 20 → త్రిభుజం లేదు. | (b) 20 > 5 + 10 = 15 → లేదు. | (c) 40 > 12 + 20 = 32 → లేదు.']),
 (382, 'Figure it Out 7.2 – ప్ర.3; ప్రశ్నలు', [
  '3) అవును, ఎప్పుడూ: చిన్న రెండు పొడవుల్లో ప్రతిదీ అతి పెద్ద దాని కంటే చిన్నది/సమానం కాబట్టి అది (పెద్దది + మరొకటి) కంటే తప్పక చిన్నది. కనీసం రెండు పోలికలు ఎప్పుడూ నిజం.',
  'పెరిగే క్రమంలో రాస్తే మొదటి రెండు (చిన్నవి) వెంటనే తేలిపోతాయి. | కాబట్టి పోల్చవలసింది ఒక్కటే: అతి పెద్ద పొడవు < మిగతా రెండింటి మొత్తం?',
  '4, 5, 8: 8 < 4 + 5 = 9 ✓. మిగతా రెండు భుజాలు (4, 5) 8 కంటే చిన్నవి కాబట్టి వాటిని చూడనవసరం లేదు.']),
 (384, 'వృత్తాల దృశ్యం', [
  'AX = 4, AB = 8 → BX = 8 − 4 = 4 సెం.మీ. | B కేంద్ర వృత్తం వ్యాసార్ధం 5 > 4 → అది X ను దాటి A వృత్తంలోకి వస్తుంది → రెండు బిందువుల వద్ద ఖండన.']),
 (386, 'Figure it Out 7.3', [
  '(a) 2, 2, 5: 5 > 2 + 2 → కాదు. | (b) 3, 4, 6: 6 < 3 + 4 = 7 → అవును. | (c) 2, 4, 8: 8 > 2 + 4 → కాదు. | (d) 5, 5, 8: 8 < 10 → అవును. | (e) 10, 20, 25: 25 < 30 → అవును. | (f) 10, 20, 35: 35 > 30 → కాదు. | (g) 24, 26, 28: 28 < 50 → అవును.']),
 (388, 'వృత్తాల మూడు సందర్భాలు', [
  'సందర్భం 1 (మొత్తం = పెద్ద పొడవు): వృత్తాలు ఒక బిందువు వద్ద తాకుతాయి – ఆ బిందువు AB పైనే → త్రిభుజం లేదు.',
  'సందర్భం 2 (మొత్తం < పెద్ద పొడవు): వృత్తాలు కలవవు → త్రిభుజం లేదు.',
  'సందర్భం 3 (మొత్తం > పెద్ద పొడవు): వృత్తాలు రెండు బిందువుల వద్ద ఖండించుకుంటాయి → త్రిభుజం ఉంది.']),
 (390, 'ఉదాహరణలు; Figure it Out 7.4 – ప్ర.1–3', [
  '(a) తాకే వృత్తాలు: 3, 4, 7; 2, 6, 8; 5, 5, 10. | (b) కలవని వృత్తాలు: 3, 4, 8; 2, 3, 6; 1, 2, 5.',
  'పూర్తి పద్ధతి: 1. అతి పెద్ద పొడవు గుర్తించాలి. 2. మిగతా రెండింటి మొత్తం కనుక్కోవాలి. 3. మొత్తం > పెద్ద పొడవు అయితే త్రిభుజం ఉంటుంది; లేకపోతే ఉండదు.',
  '1) (a) 1, 100, 100: 100 < 1 + 100 → ఉంది. | (b) 3, 6, 9: 9 = 3 + 6 → లేదు. | (c) 1, 1, 5: 5 > 2 → లేదు. | (d) 5, 10, 12: 12 < 15 → ఉంది.',
  '2) అవును: 50 < 50 + 50. | ఏ పొడవు a కైనా a < a + a కాబట్టి ప్రతి పొడవుతో సమబాహు త్రిభుజం ఉంటుంది.',
  '3) (a) 1, 100: మూడవ భుజం 99, 101 మధ్య → 99.5, 100, 100.5, 100.7, 99.4. | (b) 5, 5: 0, 10 మధ్య → 1, 3, 4, 5, 9.5. | (c) 3, 7: 4, 10 మధ్య → 5, 6, 7, 8, 9.5.']),
 (392, 'మూడవ భుజం – అన్ని వీలైన విలువలు', [
  'నియమం: మూడవ భుజం (రెండు భుజాల భేదం) కంటే ఎక్కువ, (రెండు భుజాల మొత్తం) కంటే తక్కువ. | (a) 99 < x < 101 | (b) 0 < x < 10 | (c) 4 < x < 10.']),
 (394, 'Figure it Out 7.5; 7.3.2', [
  '1) ప్రతిదానికీ: 1. ఒక భుజాన్ని ఆధారంగా గీయాలి. 2. ఒక చివర ఇచ్చిన కోణాన్ని కోణమానినితో గీయాలి. 3. ఆ కిరణంపై రెండవ భుజం పొడవు గుర్తించాలి. 4. కలపాలి.',
  '(a) ఆధారం 7 సెం.మీ., కోణం 75°, రెండవ భుజం 3 సెం.మీ. | (b) ఆధారం 6 సెం.మీ., 25°, 3 సెం.మీ. | (c) ఆధారం 8 సెం.మీ., 120°, 3 సెం.మీ. (అధికకోణ త్రిభుజం).',
  'Math Talk: కోణం 0° కంటే ఎక్కువ, 180° కంటే తక్కువ ఉన్నంత వరకు ఏ రెండు భుజాల పొడవులకైనా త్రిభుజం ఎప్పుడూ వస్తుంది – రెండు చివరలను కలిపే మూడవ భుజం ఎప్పుడూ గీయవచ్చు. కోణం 180° అయితే సరళ రేఖ అవుతుంది.']),
 (396, 'Figure it Out 7.6; త్రిభుజాలు ఎప్పుడూ ఉంటాయా?', [
  '1) ప్రతిదానికీ: ఆధారం గీసి, రెండు చివరల ఇచ్చిన కోణాలు గీసి, కిరణాలు కలిసిన బిందువును మూడవ శీర్షంగా తీసుకోవాలి.',
  '(a) 75°, 5 సెం.మీ., 75° – సమద్విబాహు (మూడవ కోణం 30°). | (b) 25°, 3 సెం.మీ., 60° (మూడవ కోణం 95°). | (c) 120°, 6 సెం.మీ., 30° (మూడవ కోణం 30°).',
  'ప్రతి జతకూ త్రిభుజం ఉండదు. ఉదా: 90°, 90°; 100°, 95°; 120°, 60°; 40°, 150° – కిరణాలు కలవవు.']),
 (398, '∠B విలువ; Figure it Out 7.7 – ప్ర.1', [
  '(a) ∠B = 150°, 160° వంటివి – రేఖలు కలవవు. | (b) కలవకుండా ఉండే అతి చిన్న ∠B: B గుండా రేఖ l కు సమాంతరమైనప్పుడు → 40° + ∠B = 180° → ∠B = 140°.',
  '∠B ≥ 140° అయితే త్రిభుజం ఉండదు. AB పొడవుకు దీనితో సంబంధం లేదు.',
  '1) (a) 30°: సాధ్యం – 150° కంటే తక్కువ (50°, 100°); అసాధ్యం – 150° లేదా ఎక్కువ (150°, 170°).',
  '(b) 70°: సాధ్యం – 110° కంటే తక్కువ (60°, 80°); అసాధ్యం – 110°, 140°.',
  '(c) 54°: సాధ్యం – 126° కంటే తక్కువ (90°, 64°); అసాధ్యం – 126°, 154°.',
  '(d) 144°: సాధ్యం – 36° కంటే తక్కువ (20°, 35°); అసాధ్యం – 36°, 90°.']),
 (400, 'Figure it Out 7.7 – ప్ర.2; మూడవ కోణం', [
  '2) (a) 35° + 150° = 185° ≥ 180° → కాదు. | (b) 70° + 30° = 100° → అవును. | (c) 90° + 85° = 175° → అవును. | (d) 50° + 150° = 200° → కాదు.',
  'నియమం: రెండు కోణాల మొత్తం 180° కంటే తక్కువ ↔ త్రిభుజం ఉంటుంది.',
  '60°, 70°: మూడవ కోణం 50°. ఆధారం 5 సెం.మీ. అయినా 7 సెం.మీ. అయినా మారదు – మూడవ కోణం మధ్య భుజం పొడవుపై ఆధారపడదు.']),
 (402, 'Figure it Out 7.8', [
  '∠XAB = ∠B = 50°, ∠YAC = ∠C = 70° (ఏకాంతర కోణాలు) → ∠BAC = 180° − 50° − 70° = 60°.',
  '1) పద్ధతి: శీర్షం A గుండా BC కి సమాంతరంగా XY. ∠XAB = ∠B, ∠YAC = ∠C; ∠XAB + ∠BAC + ∠YAC = 180°.',
  '(a) 36°, 72°: 180° − 108° = 72°. | (b) 150°, 15°: 180° − 165° = 15°. | (c) 90°, 30°: 60°. | (d) 75°, 45°: 60°.',
  '2) కాదు – 70° + 70° + 70° = 210° ≠ 180°. | రెండు కోణాలు 70° అయితే మూడవది 180° − 140° = 40°. | మూడూ సమానమైతే ప్రతిదీ 180° ÷ 3 = 60°.',
  '3) ∠B + ∠C = 180° − 50° = 130°; ∠B = ∠C → ∠B = ∠C = 65°.']),
 (406, 'కాగితం మడత – కోణాల మొత్తం', [
  'మూడు మూలలను ఆధారంపై ఒక బిందువు వద్దకు మడిస్తే మూడు కోణాలూ పక్కపక్కన చేరి సరళ రేఖ (సరళ కోణం) ఏర్పరుస్తాయి → మొత్తం 180°.']),
 (408, '7.3.4 బాహ్య కోణాలు', [
  '∠A + ∠B + ∠ACB = 180° (కోణాల మొత్తం). | ∠ACD + ∠ACB = 180° (సరళ కోణం). | కాబట్టి ∠ACD = ∠A + ∠B – బాహ్య కోణం ఎదుటి రెండు అంతర కోణాల మొత్తానికి సమానం.',
  'ఉదా: ∠A = 40°, ∠B = 80° → ∠ACD = 120°. | ∠A = 30°, ∠B = 45° → 75°.']),
 (410, 'ఉన్నతులు – కాగితం మడత', [
  'అధికకోణ త్రిభుజంలో: BC ని పొడిగించి, A నుండి ఆ రేఖకు లంబం గీయాలి – ఉన్నతి త్రిభుజం బయట ఉంటుంది.',
  'మడత: ఆధారం రెండు భాగాలూ ఒకదానిపై ఒకటి పడేలా, మడత పై శీర్షం గుండా వెళ్ళేలా మడవాలి. | మడతకు ఇరువైపులా ఉన్న కోణాలు సమానం, వాటి మొత్తం 180° → ప్రతిదీ 90° → మడత ఆధారానికి లంబం.']),
 (412, 'భుజమే ఉన్నతి?', [
  'అవును – లంబకోణ త్రిభుజంలో. ∠B = 90° అయితే AB ⊥ BC కాబట్టి A నుండి BC కి ఉన్నతి AB నే.']),
 (414, 'త్రిభుజ రకాలు; Figure it Out 7.9 – ప్ర.1, 2', [
  'ఇతర రకాలు: అల్పకోణ, అధికకోణ త్రిభుజాలు.',
  'అల్పకోణ త్రిభుజాన్ని “ఒక అల్పకోణం ఉన్నది” అని నిర్వచించలేం – ప్రతి త్రిభుజంలో కనీసం రెండు అల్పకోణాలు ఉంటాయి. మూడు కోణాలూ అల్పకోణాలైతేనే అల్పకోణ త్రిభుజం.',
  '1) నిర్మాణం: 1. BC = 5 సెం.మీ. గీయాలి. 2. B నుండి 6 సెం.మీ., C నుండి 5 సెం.మీ. చాపాలు – ఖండన బిందువు A. 3. AB, AC కలపాలి. 4. స్కేలును BC వెంట పెట్టి, మూలమట్టాన్ని జరిపి A గుండా BC కి లంబం AD గీయాలి.',
  '2) నిర్మాణం: 1. RY = 4 సెం.మీ. 2. R వద్ద 140° కోణం. 3. ఆ కిరణంపై TR = 7 సెం.మీ. గుర్తించి T, Y కలపాలి. 4. ∠R అధికకోణం కాబట్టి YR ని R దాటి పొడిగించి, T నుండి ఆ పొడిగింపుకు లంబం గీయాలి (ఉన్నతి త్రిభుజం బయట).']),
 (416, 'Figure it Out 7.9 – ప్ర.3, 4', [
  '3) AC = 5 సెం.మీ. ఆధారం; ∠A + ∠C = 90° అయ్యేలా ఏ జత తీసుకున్నా (30° – 60°, 45° – 45°, 20° – 70°…) ∠B = 90° వస్తుంది. | కాబట్టి అలాంటి త్రిభుజాలు అనంతం (లెక్కలేనన్ని).',
  '4) సమబాహు త్రిభుజంలో ప్రతి కోణం 60° → (i) లంబకోణ, (ii) అధికకోణ సమబాహు త్రిభుజాలు అసాధ్యం.',
  'సమద్విబాహు: (i) లంబకోణ – 45°, 45°, 90° (ఉదా: 4 సెం.మీ., 90°, 4 సెం.మీ.). | (ii) అధికకోణ – 30°, 30°, 120° (ఉదా: 4 సెం.మీ., 120°, 4 సెం.మీ.).']),
 (418, 'పజిల్ – పెట్టెలో అతి చిన్న దారి', [
  'పెట్టెను విప్పి చదును (net) చేయాలి. చదునైన కాగితంపై సాలీడు మూల నుండి ఎదుటి మూలకు గీసిన సరళ రేఖే అతి చిన్న దారి – అది రెండు ముఖాల మీదుగా, ఒక అంచును మధ్యలో దాటుతూ వెళ్తుంది.',
  'వేర్వేరు జతల ముఖాలను విప్పి వచ్చే సరళ రేఖల్లో అతి చిన్నదాన్ని ఎంచుకోవాలి (అంచుల వెంటే వెళ్ళే దారి కంటే ఇది చిన్నది – త్రిభుజ అసమానత).']),
]
